import React from 'react';
import { Container, Row, Col, Button } from 'react-bootstrap';
import { FaFish, FaWater, FaHandHoldingWater, FaLeaf, FaUsers, FaChartLine, FaShoppingBasket } from 'react-icons/fa';

const Home = () => (
  <div className="home-page">
    {/* Hero Section */}
    <section className="hero-section">
      <div className="hero-overlay"></div>
      <Container className="hero-content">
        <Row className="justify-content-center align-items-center">
          <Col lg={8} className="text-center">
            <h1 className="hero-title">BUKANI MAMA TOTO</h1>
            <p className="hero-subtitle">Empowering Women Through Sustainable Aquaculture</p>
            <p className="hero-text">
              A community-based women's group dedicated to fish farming and family nutrition, 
              transforming lives along Lake Victoria.
            </p>
            <div className="hero-buttons">
              <Button variant="primary" className="me-3">Our Products</Button>
              <Button variant="outline-light">Join Our Mission</Button>
            </div>
          </Col>
        </Row>
      </Container>
      
      <div className="water-animation"></div>
    </section>

    {/* Mission Section */}
    <section className="mission-section py-5">
      <Container>
        <Row className="justify-content-center">
          <Col lg={8} className="text-center mb-5">
            <h2 className="section-title">Our Mission & Values</h2>
            <p className="section-subtitle">
              We're dedicated to empowering women through sustainable aquaculture practices
            </p>
          </Col>
        </Row>
        
        <Row className="g-4">
          <Col md={4}>
            <div className="mission-card glass-card">
              <div className="mission-icon">
                <FaUsers />
              </div>
              <h3>Women Empowerment</h3>
              <p>
                Creating economic opportunities for women through fish farming, 
                promoting financial independence and leadership.
              </p>
            </div>
          </Col>
          
          <Col md={4}>
            <div className="mission-card glass-card">
              <div className="mission-icon">
                <FaLeaf />
              </div>
              <h3>Sustainability</h3>
              <p>
                Environmentally responsible aquaculture practices that protect 
                Lake Victoria's ecosystem for future generations.
              </p>
            </div>
          </Col>
          
          <Col md={4}>
            <div className="mission-card glass-card">
              <div className="mission-icon">
                <FaHandHoldingWater />
              </div>
              <h3>Nutrition Security</h3>
              <p>
                Providing high-quality protein sources to improve family nutrition 
                and combat malnutrition in our communities.
              </p>
            </div>
          </Col>
        </Row>
      </Container>
    </section>

    {/* Products Section */}
    <section className="products-section py-5">
      <Container>
        <Row className="justify-content-center mb-5">
          <Col lg={8} className="text-center">
            <h2 className="section-title">Our Fresh Products</h2>
            <p className="section-subtitle">
              Sustainably farmed fish from Lake Victoria
            </p>
          </Col>
        </Row>
        
        <Row className="g-4">
          <Col lg={4} md={6}>
            <div className="product-card glass-card">
              <div className="product-image tilapia"></div>
              <div className="product-content">
                <h3>Tilapia</h3>
                <p>Freshly harvested Nile Tilapia, sustainably farmed in Lake Victoria</p>
                <div className="product-meta">
                  <span className="price">KES 400/kg</span>
                  <Button variant="outline-primary">Order Now</Button>
                </div>
              </div>
            </div>
          </Col>
          
          <Col lg={4} md={6}>
            <div className="product-card glass-card">
              <div className="product-image catfish"></div>
              <div className="product-content">
                <h3>Catfish</h3>
                <p>Nutrient-rich African Catfish, perfect for family meals</p>
                <div className="product-meta">
                  <span className="price">KES 350/kg</span>
                  <Button variant="outline-primary">Order Now</Button>
                </div>
              </div>
            </div>
          </Col>
          
          <Col lg={4} md={6}>
            <div className="product-card glass-card">
              <div className="product-image smoked"></div>
              <div className="product-content">
                <h3>Smoked Fish</h3>
                <p>Traditionally smoked fish with rich flavor and long shelf life</p>
                <div className="product-meta">
                  <span className="price">KES 600/kg</span>
                  <Button variant="outline-primary">Order Now</Button>
                </div>
              </div>
            </div>
          </Col>
        </Row>
      </Container>
    </section>

    {/* Impact Section */}
    <section className="impact-section py-5">
      <Container>
        <Row className="justify-content-center mb-5">
          <Col lg={8} className="text-center">
            <h2 className="section-title">Our Community Impact</h2>
            <p className="section-subtitle">
              Transforming lives through sustainable aquaculture
            </p>
          </Col>
        </Row>
        
        <Row className="g-4">
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">250+</div>
              <div className="stat-label">Women Empowered</div>
            </div>
          </Col>
          
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">15</div>
              <div className="stat-label">Farming Groups</div>
            </div>
          </Col>
          
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">50K+</div>
              <div className="stat-label">Fish Harvested</div>
            </div>
          </Col>
          
          <Col md={3} className="text-center">
            <div className="impact-stat">
              <div className="stat-value">100%</div>
              <div className="stat-label">Sustainable Practices</div>
            </div>
          </Col>
        </Row>
        
        <Row className="mt-5">
          <Col lg={6} className="mb-4 mb-lg-0">
            <div className="impact-story glass-card">
              <div className="story-image"></div>
              <div className="story-content">
                <h3>Mary's Story</h3>
                <p>
                  "Before joining Bukani Mama Toto, I struggled to feed my family. 
                  Now, through fish farming, I earn a steady income and provide nutritious 
                  meals for my children."
                </p>
                <div className="story-author">Mary Atieno, Group Member since 2020</div>
              </div>
            </div>
          </Col>
          
          <Col lg={6}>
            <div className="impact-video glass-card">
              <div className="video-placeholder"></div>
              <div className="video-content">
                <h3>Our Farming Journey</h3>
                <p>
                  Watch how we're transforming lives through sustainable aquaculture 
                  along Lake Victoria.
                </p>
                <Button variant="primary">Watch Video</Button>
              </div>
            </div>
          </Col>
        </Row>
      </Container>
    </section>

    {/* CTA Section */}
    <section className="cta-section py-5">
      <Container>
        <Row className="justify-content-center">
          <Col lg={8} className="text-center">
            <h2 className="cta-title">Join Our Sustainable Movement</h2>
            <p className="cta-text">
              Support women empowerment and sustainable aquaculture while enjoying 
              fresh, nutritious fish from Lake Victoria.
            </p>
            <div className="cta-buttons">
              <Button variant="primary" className="me-3">Shop Now</Button>
              <Button variant="outline-light">Learn More</Button>
            </div>
          </Col>
        </Row>
      </Container>
    </section>

    <style jsx>{`
